// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Typed errors, exit codes, what-why-fix messages
// Flo: error set > map error to exit code 0-4 > map error to 3-line message
// I/O: anyerror (caller) > u8 exit code + Mesg (stderr text)
// ===================================================================
const std = @import("std");
const CF = .{ .okay = 0, .fail = 1, .usag = 2, .drif = 3, .bloc = 4 };
pub const Erro = error{ BadUsage, BadConfig, Drift, Blocked, Fail, NeedVendor, OverCap, KillOn, BadUrl, BlockedHost, NotText, TooBig, RedirectLoop, TooManyRedirects, Timeout, CharUnsupported, HashMismatch, NoKey };
pub const Mesg = struct { what: []const u8, whyz: []const u8, fixz: []const u8 };
pub fn exitCode(erro: anyerror) u8 { return switch (erro) { error.BadUsage, error.BadUrl, error.BlockedHost => CF.usag, error.Drift => CF.drif, error.Blocked => CF.bloc, else => CF.fail }; }
pub fn mesg(erro: anyerror) Mesg { return switch (erro) { error.BadUsage => .{ .what = "bad usage", .whyz = "unknown command or flag", .fixz = "run: scra help" }, error.BadConfig => .{ .what = "bad config", .whyz = "aa-conf-main.json has a bad or unknown value", .fixz = "fix the key named above or delete the file for defaults" }, error.Drift => .{ .what = "drift", .whyz = "page shape changed from the saved fixture", .fixz = "review the parser, update the fixture" }, error.Blocked => .{ .what = "blocked", .whyz = "the host served a block page", .fixz = "climb a tier or wait; never retry the same vendor" }, error.NeedVendor => .{ .what = "needs vendor", .whyz = "own GET failed (TLS or block)", .fixz = "let the tier ladder pick a vendor" }, error.OverCap => .{ .what = "spend cap hit", .whyz = "capz_usdz_mont or a vendor credit cap is used up", .fixz = "raise the cap in aa-conf-main.json, then run with go" }, error.KillOn => .{ .what = "kill switch on", .whyz = "all spend is halted", .fixz = "run: scra kill --off" }, error.BadUrl => .{ .what = "bad url", .whyz = "not a plain http(s) URL (userinfo, odd scheme, too long)", .fixz = "pass a full http:// or https:// URL" }, error.BlockedHost => .{ .what = "host refused", .whyz = "private, loopback, link-local or metadata address", .fixz = "only public hosts are fetched" }, error.NotText => .{ .what = "not text", .whyz = "content type is image, video, font or binary", .fixz = "scra stores text only (HTML, JSON, XML)" }, error.TooBig => .{ .what = "body too big", .whyz = "over fetc_body_maxz (also stops gzip bombs)", .fixz = "raise fetc_body_maxz or skip the page" }, error.RedirectLoop => .{ .what = "redirect loop", .whyz = "a redirect points back to a visited URL", .fixz = "skip this URL" }, error.TooManyRedirects => .{ .what = "too many redirects", .whyz = "more hops than fetc_redi_maxz", .fixz = "raise fetc_redi_maxz or skip" }, error.Timeout => .{ .what = "timeout", .whyz = "no answer within fetc_time_seco", .fixz = "retry later or raise fetc_time_seco" }, error.CharUnsupported => .{ .what = "charset unsupported", .whyz = "page is not UTF-8, Latin-1 or UTF-16", .fixz = "skip or use a vendor tier" }, error.NoKey => .{ .what = "no vendor key", .whyz = "key file missing or empty", .fixz = "put the key on line 1 of ~/.zz-base-home-secr/scra/<vendor>.key" }, error.HashMismatch => .{ .what = "stored file damaged", .whyz = "file content does not match its hash", .fixz = "refetch the page" }, else => .{ .what = "failed", .whyz = @errorName(erro), .fixz = "re-run with --json and check status" } }; }
